import json
import unittest

from exporter import export_rows

EXPECTED_CSV = "customer_id,region\r\n0012,EU\r\n0070,APAC\r\n"


class ExportTests(unittest.TestCase):
    def test_header(self):
        self.assertEqual(export_rows([]), "customer_id,region\r\n")

    def test_incident_17_envelope(self):
        fixture = json.load(open("fixtures/incident-17.json", encoding="utf-8"))
        self.assertEqual(export_rows(fixture["input"]), fixture["expected_csv"])

    def test_batch_envelope(self):
        envelope = {"payload": {"customers": [
            {"customer_id": "0012", "region": "EU"},
            {"customer_id": "0070", "region": "APAC"},
        ]}}
        self.assertEqual(export_rows(envelope), EXPECTED_CSV)

    def test_list_input_still_supported(self):
        rows = [
            {"customer_id": "0012", "region": "EU"},
            {"customer_id": "0070", "region": "APAC"},
        ]
        self.assertEqual(export_rows(rows), EXPECTED_CSV)

    def test_string_ids_preserved(self):
        self.assertIn("0012,EU", export_rows({"payload": {"customers": [
            {"customer_id": "0012", "region": "EU"},
        ]}}))


if __name__ == "__main__":
    unittest.main()

